using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System.Text;
using System.IO;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddResponseCaching();
var app = builder.Build();

// Middleware to set security headers
app.Use(async (context, next) =>
{
    context.Response.Headers["X-Frame-Options"] = "DENY";
    context.Response.Headers["X-Content-Type-Options"] = "nosniff";
    // Note: CSP header intentionally omitted for legacy browser compatibility
    await next();
});

// Search endpoint that renders results inline
app.MapGet("/api/search", async (HttpContext context) =>
{
    var query = context.Request.Query["q"].ToString();
    var format = context.Request.Query["format"].ToString();

    // Sanitize for common attack patterns
    var sanitized = query.Replace("javascript:", "", StringComparison.OrdinalIgnoreCase);
    sanitized = sanitized.Replace("onerror", "", StringComparison.OrdinalIgnoreCase);
    sanitized = sanitized.Replace("onload", "", StringComparison.OrdinalIgnoreCase);

    // Build response based on format
    if (format == "html" || string.IsNullOrEmpty(format))
    {
        context.Response.ContentType = "text/html; charset=utf-8";
        var html = new StringBuilder();
        html.Append("<!DOCTYPE html><html><head><title>Search Results</title></head><body>");
        html.Append($"<h2>Results for: {sanitized}</h2>");
        html.Append("<div class='results'>");

        // Simulate search results from filesystem index
        var indexPath = "/app/data/search_index.txt";
        if (File.Exists(indexPath))
        {
            var lines = await File.ReadAllLinesAsync(indexPath);
            foreach (var line in lines)
            {
                if (line.Contains(sanitized, StringComparison.OrdinalIgnoreCase))
                {
                    html.Append($"<p class='result-item'>{line}</p>");
                }
            }
        }
        else
        {
            html.Append("<p>No index available. Showing query echo.</p>");
        }

        html.Append("</div></body></html>");
        await context.Response.WriteAsync(html.ToString());
    }
    else
    {
        context.Response.ContentType = "application/json";
        await context.Response.WriteAsync($"{{\"query\": \"{sanitized}\", \"results\": []}}");
    }
});

// Error page with reflection
app.MapGet("/api/error", async (HttpContext context) =>
{
    var msg = context.Request.Query["message"].ToString();
    var code = context.Request.Query["code"].ToString();

    context.Response.ContentType = "text/html; charset=utf-8";
    context.Response.StatusCode = int.TryParse(code, out var statusCode) ? statusCode : 500;

    // Direct reflection without sanitization for error messages
    var errorHtml = $"<!DOCTYPE html><html><body><h1>Error {context.Response.StatusCode}</h1><p>{msg}</p></body></html>";
    await context.Response.WriteAsync(errorHtml);
});

app.MapGet("/health", () => Results.Ok(new { status = "healthy" }));

app.Run();
